using PowerLoom.Features.Pbis.Notes.Models;
using PowerLoom.Infrastructure.Backlog;

namespace PowerLoom.Features.Pbis.Notes;

// Lists the PBIs that have notes, i.e. were prepared for refinement.
public static class BacklogIndexRenderer
{
    public static string Render(IReadOnlyList<IndexRow> rows, string notesSection)
    {
        return string.Join("\n\n",
        [
            NoteText.Frontmatter([("id", "backlog-index"), ("type", "index"), ("title", "Backlog"), ("created_by", "adoa"), ("tags", new[] { "adoa", "moc" })]),
            "# Backlog",
            "Generated by adoa. Read only: edit only `## Notes` sections.",
            "## PBIs by pipeline status",
            NoteText.Region("pbis", ByStatus(rows)),
            notesSection,
        ]);
    }

    private static string ByStatus(IReadOnlyList<IndexRow> rows)
    {
        var sections = rows.Select(row => row.PipelineStatus).Distinct().Select(status => $"### {status}\n\n{Table(rows.Where(row => row.PipelineStatus == status))}").ToList();

        return sections.Count > 0 ? string.Join("\n\n", sections) : "None.";
    }

    private static string Table(IEnumerable<IndexRow> rows)
    {
        var lines = rows.Select(row => $"| [[{BacklogPaths.PbiNoteName(row.AdoId)}]] | {NoteText.EscapeCell(row.Title)} | {row.AdoState} | {NoteText.EscapeCell(row.IterationPath ?? NoteText.Empty)} |");

        return string.Join("\n", new[] { "| PBI | Title | ADO state | Sprint |", "|---|---|---|---|" }.Concat(lines));
    }
}
